function phoneTail(phone, dial) {
  let digits = (phone ?? "").replace(/\D/g, "").replace(/^00/, "");
  if (dial && digits.startsWith(dial))
    digits = digits.slice(dial.length);
  digits = digits.replace(/^0+/, "");
  return digits.length >= 7 ? digits : null;
}

