async function operationsOverview(db4, userId, input2) {
  const scope = orderScope(await shopGrants(db4, userId), input2.shopId);
  const where = filteredOrders(scope, input2);
  const [statuses, unassigned, overdue, recent] = await Promise.all([
    db4.pancakeOrder.groupBy({ by: ["status"], where, _count: { _all: true } }),
    db4.pancakeOrder.count({ where: { AND: [where, { sellerId: null }] } }),
    db4.pancakeTask.count({
      where: { order: scope, status: "OPEN", dueAt: { lt: new Date } }
    }),
    db4.pancakeOrder.findMany({
      where,
      select: orderSelect,
      orderBy: [
        { sourceUpdatedAt: "desc" },
        { shopId: "asc" },
        { orderId: "asc" }
      ],
      take: PANCAKE.overviewRows
    })
  ]);
  const total = (values) => statuses.reduce((sum, row) => sum + (values.includes(row.status) ? row._count._all : 0), 0);
  return {
    orders: statuses.reduce((sum, row) => sum + row._count._all, 0),
    pending: total(ORDER_VIEWS.pending.statuses),
    shipping: total(ORDER_VIEWS.shipping.statuses),
    returns: total(ORDER_VIEWS.returns.statuses),
    unassigned,
    overdue,
    statuses: statuses.map((row) => ({
      status: row.status,
      count: row._count._all
    })),
    recent: recent.map((row) => ({
      ...row,
      totalPrice: row.totalPrice.toString(),
      sourceCreatedAt: row.sourceCreatedAt.toISOString(),
      sourceUpdatedAt: row.sourceUpdatedAt.toISOString()
    }))
  };
}
