async function approveEmployee(db4, userId, input2) {
  await assertShopManager(db4, userId, input2.shopId);
  const emp = await db4.pancakeEmployee.findUnique({
    where: {
      shopId_employeeId: {
        shopId: input2.shopId,
        employeeId: input2.employeeId
      }
    }
  });
  if (!emp)
    throw new PancakeAccessError;
  const meta3 = parseEmployeeMeta(emp.raw);
  const email3 = (emp.email?.trim() || `pancake.${emp.employeeId}@pancake-crm.local`).toLowerCase();
  const existingUser = await db4.user.findUnique({ where: { email: email3 } });
  const targetUser = existingUser ? await db4.user.update({
    where: { id: existingUser.id },
    data: {
      image: existingUser.image ?? meta3.avatarUrl
    }
  }) : await db4.user.create({
    data: {
      id: randomUUID3(),
      name: emp.name,
      email: email3,
      emailVerified: true,
      image: meta3.avatarUrl
    }
  });
  await db4.member.upsert({
    where: {
      organizationId_userId: {
        organizationId: "workspace",
        userId: targetUser.id
      }
    },
    create: {
      id: randomUUID3(),
      organizationId: "workspace",
      userId: targetUser.id,
      role: "member",
      createdAt: new Date
    },
    update: {}
  });
  return db4.pancakeShopMember.upsert({
    where: {
      shopId_userId: { shopId: input2.shopId, userId: targetUser.id }
    },
    create: {
      shopId: input2.shopId,
      userId: targetUser.id,
      role: input2.role,
      employeeId: emp.employeeId
    },
    update: {
      role: input2.role,
      employeeId: emp.employeeId
    },
    select: { shopId: true, userId: true, role: true, employeeId: true }
  });
}
async function approveAllEmployees(db4, userId, shopId) {
  await assertShopManager(db4, userId, shopId);
  const [employees, members] = await Promise.all([
    db4.pancakeEmployee.findMany({ where: { shopId } }),
    db4.pancakeShopMember.findMany({ where: { shopId } })
  ]);
  const mappedIds = new Set(members.flatMap((m3) => m3.employeeId ? [m3.employeeId] : []));
  let approved = 0;
  for (const emp of employees) {
    if (mappedIds.has(emp.employeeId))
      continue;
    const meta3 = parseEmployeeMeta(emp.raw);
    const isManager = meta3.roleCode === "1" || meta3.roleCode === "2";
    await approveEmployee(db4, userId, {
      shopId,
      employeeId: emp.employeeId,
      role: isManager ? "MANAGER" : "TELESALE"
    });
    approved += 1;
  }
  return { approved };
}
